/**
 * Episode 005, "Was the Ramayana real? The flight path Valmiki recorded".
 * One player renders any cut: a chapter's Short (1080x1920, Hindi, with its "next part" line) or the long video
 * (1920x1080, all chapters, Hindi or English audio). Timing per cut comes from timing.ts (generated by
 * episodes/005-ramayana-evidence/tools/cuts.py from the picked takes); shots from shots.ts.
 */
import React from 'react';
import {AbsoluteFill, Audio, interpolate, Sequence, staticFile, useCurrentFrame, useVideoConfig} from 'remotion';
import {BigText, Credit, FollowCard, HI_NAME, MapView, PartTag, Pic, Tag, ThenNow, Wipe} from './kit';
import {ChapterCard, Painting, PhotoCard, PlaceChip, StackThenNow, TourCard} from './fx';
import {DIMS} from './dims';
import {CHAPTERS, credit, Shot, Visual} from './shots';
import {CUTS} from './timing';
import {CLAUSES} from './clauses';

const FPS = 30;
/** Frames from a line's start to the start of its phrase `ph` (measured in the take by tools/clauses.py). */
const phOff = (id: string, ph?: number) => (ph ? Math.round((CLAUSES[id]?.[ph] ?? 0) * FPS) : 0);

const XF = 12; // crossfade frames between shots

const Fade: React.FC<{d: number; children: React.ReactNode}> = ({d, children}) => {
  const f = useCurrentFrame();
  const o = interpolate(f, [0, XF], [0, 1], {extrapolateRight: 'clamp'});
  return <AbsoluteFill style={{opacity: d > XF ? o : 1}}>{children}</AbsoluteFill>;
};

const ShotView: React.FC<{v: Visual; dur: number; i: number; rel: (id: string, ph: number) => number; id: string}> = ({v, dur, i, rel, id}) => {
  const {height: H} = useVideoConfig();
  const tall = H > 1500;
  if ('pic' in v) {
    const [w, h] = DIMS[v.pic];
    if (v.pic.startsWith('now_') && v.fx?.length) {
      return <AbsoluteFill><Painting src={v.pic} w={w} h={h} dur={dur} a={v.a} b={v.b} fx={v.fx} seed={i * 13 + 5} /><Credit text={v.credit} />
        {v.place && <div style={{position: 'absolute', top: tall ? 260 : 40, left: 0, right: 0, textAlign: 'center'}}><PlaceChip text={v.place} size={40} /></div>}</AbsoluteFill>;
    }
    if (v.pic.startsWith('now_')) {
      if (tall) return <PhotoCard src={v.pic} w={w} h={h} dur={dur} place={v.place} credit={v.credit} a={v.a} b={v.b} />;
      return (
        <AbsoluteFill>
          <Pic src={v.pic} w={w} h={h} dur={dur} a={v.a} b={v.b} /><Credit text={v.credit} />
          {v.place && <div style={{position: 'absolute', top: 40, left: 40}}><PlaceChip text={v.place} size={40} /></div>}
        </AbsoluteFill>
      );
    }
    return <Painting src={v.pic} w={w} h={h} dur={dur} a={v.a} b={v.b} fx={v.fx} seed={i * 13 + 5} glowAt={v.glowAt} flip={i % 2 === 1} clip={v.clip} />;
  }
  if ('wipe' in v) {
    const [t, n] = v.wipe, at = v.atPh !== undefined ? Math.max(12, rel(id, v.atPh) + 4) : Math.round(dur * (v.at ?? 0.45));
    const [tw, th] = DIMS[t], [nw, nh] = DIMS[n];
    if (tall) return <StackThenNow then={[t, tw, th]} now={[n, nw, nh]} dur={dur} at={at} credit={v.credit} place={v.place} />;
    return (
      <AbsoluteFill>
        <Wipe at={at} then={<Pic src={t} w={tw} h={th} dur={dur} a={v.a} b={v.b} />}
          now={<><Pic src={n} w={nw} h={nh} dur={dur} a={[0.5, 0.5, 1]} b={[0.5, 0.5, 1.06]} /><Credit text={v.credit} /></>} />
        <ThenNow at={at} />
      </AbsoluteFill>
    );
  }
  if ('map' in v) {
    const {tour, ...m} = v.map;
    // Tour stops land on the phrase that names the place.
    const at = tour?.map(([, , ph]) => Math.max(0, rel(id, ph)));
    return (
      <AbsoluteFill>
        <MapView dur={dur} {...m} tour={tour?.map((x) => x[0])} tourAt={at} />
        {tour?.map(([k, pic, , name], j) => {
          const [w, h] = DIMS[pic];
          const t1 = j + 1 < tour.length ? at![j + 1] + 4 : dur;
          return <TourCard key={j} src={pic} w={w} h={h} name={name ?? HI_NAME[k] ?? k} t0={at![j] + 4} t1={t1} credit={credit(pic)} />;
        })}
      </AbsoluteFill>
    );
  }
  const [w, h] = DIMS[v.bg];
  return <AbsoluteFill><Painting src={v.bg} w={w} h={h} dur={dur} b={[0.5, 0.5, 1.1]} fx={['dust']} /><FollowCard next={v.follow} /></AbsoluteFill>;
};

export const EvidenceStory: React.FC<{cut: string; chapters: string[]; audio: string; titles?: Record<string, string>}> = ({cut, chapters, audio, titles}) => {
  const T = CUTS[cut];
  const {height: H} = useVideoConfig();
  const S = (id: string) => T.lines[id]?.[0];
  const E = (id: string) => T.lines[id]?.[1];
  const shots: {from: number; s: Shot}[] = [];
  for (const c of chapters) {
    for (const s of CHAPTERS[c].shots) {
      const st = S(s.at);
      if (st !== undefined) shots.push({from: Math.max(0, st + phOff(s.at, s.ph) + (s.off ?? 0) - 8), s});
    }
  }
  shots.sort((a, b) => a.from - b.from);
  if (shots.length) shots[0].from = 0;
  const over = chapters.flatMap((c) => CHAPTERS[c].over).filter((o) => S(o.at) !== undefined);
  const isShort = H > 1500;
  return (
    <AbsoluteFill style={{background: '#120c0a'}}>
      {shots.map(({from, s}, i) => {
        const to = i + 1 < shots.length ? shots[i + 1].from + XF : T.frames;
        return (
          <Sequence key={i} from={from} durationInFrames={Math.max(1, to - from)}>
            <Fade d={i === 0 ? 0 : to - from}><ShotView v={s.v} dur={to - from} i={i} id={s.at} rel={(id, ph) => S(id)! + phOff(id, ph) - from} /></Fade>
          </Sequence>
        );
      })}
      {over.map((o, i) => {
        const from = S(o.at)! + phOff(o.at, o.ph) + (o.off ?? 0);
        const dur = o.till !== undefined ? phOff(o.at, o.till) - phOff(o.at, o.ph) : E(o.at)! - from + 14;
        return (
          <Sequence key={`o${i}`} from={from} durationInFrames={dur}>
            {o.tag && <Tag k={o.tag} />}
            {o.big && <BigText text={o.big} sub={o.sub} />}
          </Sequence>
        );
      })}
      {isShort && chapters.length === 1 && <Sequence from={0} durationInFrames={120}><PartTag n={CHAPTERS[chapters[0]].n} of={17} /></Sequence>}
      {/* Long video: a chapter card where each chapter begins (these frames are the YouTube chapter timestamps). */}
      {!isShort && chapters.map((c) => {
        const first = CHAPTERS[c].shots.map((s) => S(s.at)).filter((x) => x !== undefined) as number[];
        if (!first.length) return null;
        return <Sequence key={`ct${c}`} from={Math.min(...first)} durationInFrames={150}><ChapterCard n={CHAPTERS[c].n} title={titles?.[c] ?? ''} /></Sequence>;
      })}
      <Audio src={staticFile(audio)} />
    </AbsoluteFill>
  );
};

/** Reel / Short cover (1080x1920; Instagram's grid shows the middle 3:4). */
export const EvidenceCover: React.FC<{bg: string; title: string; sub: string; n: number; focus?: [number, number, number]}> = ({bg, title, sub, n, focus}) => {
  const [w, h] = DIMS[bg];
  return (
    <AbsoluteFill style={{background: '#120c0a'}}>
      <Pic src={bg} w={w} h={h} dur={1} a={focus} b={focus} />
      <AbsoluteFill style={{background: 'linear-gradient(180deg, rgba(18,12,10,0) 35%, rgba(18,12,10,0.88) 72%)'}} />
      <div style={{position: 'absolute', top: 1180, left: 0, right: 0, textAlign: 'center', padding: '0 60px'}}>
        <div style={{fontFamily: 'Kohinoor Devanagari, Noto Sans Devanagari, sans-serif', fontSize: 46, color: '#f6efdc', marginBottom: 18}}>
          रामायण का मार्ग · भाग {n}/17
        </div>
        <div style={{fontFamily: 'Kohinoor Devanagari, Noto Sans Devanagari, sans-serif', fontWeight: 700, fontSize: 112, lineHeight: 1.2,
          color: '#f2c14e', textShadow: '0 6px 24px #000'}}>{title}</div>
        <div style={{fontFamily: 'Kohinoor Devanagari, Noto Sans Devanagari, sans-serif', fontSize: 54, color: '#f6efdc', marginTop: 16}}>{sub}</div>
      </div>
    </AbsoluteFill>
  );
};

